Author: Philip Withnall <pwithnall@endlessos.org>
Date:   Thu Oct 1 11:45:22 2020 +0100

    gdatetime: Avoid integer overflow creating dates too far in the past

    oss-fuzz#22758

    Signed-off-by: Philip Withnall <pwithnall@endlessos.org>

diff --git a/glib/gdatetime.c b/glib/gdatetime.c
index f93d7d88c..a14124d7c 100644
--- a/glib/gdatetime.c
+++ b/glib/gdatetime.c
@@ -935,236 +935,238 @@ g_date_time_new_from_unix (GTimeZone *tz,
  * time zone @tz.  The time is as accurate as the system allows, to a
  * maximum accuracy of 1 microsecond.
  *
  * This function will always succeed unless GLib is still being used after the
  * year 9999.
  *
  * You should release the return value by calling g_date_time_unref()
  * when you are done with it.
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  **/
 GDateTime *
 g_date_time_new_now (GTimeZone *tz)
 {
   gint64 now_us;

   now_us = g_get_real_time ();

   return g_date_time_new_from_unix (tz, now_us);
 }

 /**
  * g_date_time_new_now_local:
  *
  * Creates a #GDateTime corresponding to this exact instant in the local
  * time zone.
  *
  * This is equivalent to calling g_date_time_new_now() with the time
  * zone returned by g_time_zone_new_local().
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  **/
 GDateTime *
 g_date_time_new_now_local (void)
 {
   GDateTime *datetime;
   GTimeZone *local;

   local = g_time_zone_new_local ();
   datetime = g_date_time_new_now (local);
   g_time_zone_unref (local);

   return datetime;
 }

 /**
  * g_date_time_new_now_utc:
  *
  * Creates a #GDateTime corresponding to this exact instant in UTC.
  *
  * This is equivalent to calling g_date_time_new_now() with the time
  * zone returned by g_time_zone_new_utc().
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  **/
 GDateTime *
 g_date_time_new_now_utc (void)
 {
   GDateTime *datetime;
   GTimeZone *utc;

   utc = g_time_zone_new_utc ();
   datetime = g_date_time_new_now (utc);
   g_time_zone_unref (utc);

   return datetime;
 }

 /**
  * g_date_time_new_from_unix_local:
  * @t: the Unix time
  *
  * Creates a #GDateTime corresponding to the given Unix time @t in the
  * local time zone.
  *
  * Unix time is the number of seconds that have elapsed since 1970-01-01
  * 00:00:00 UTC, regardless of the local time offset.
  *
  * This call can fail (returning %NULL) if @t represents a time outside
  * of the supported range of #GDateTime.
  *
  * You should release the return value by calling g_date_time_unref()
  * when you are done with it.
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  **/
 GDateTime *
 g_date_time_new_from_unix_local (gint64 t)
 {
   GDateTime *datetime;
   GTimeZone *local;

-  if (t > G_MAXINT64 / USEC_PER_SECOND)
+  if (t > G_MAXINT64 / USEC_PER_SECOND ||
+      t < G_MININT64 / USEC_PER_SECOND)
     return NULL;

   local = g_time_zone_new_local ();
   datetime = g_date_time_new_from_unix (local, t * USEC_PER_SECOND);
   g_time_zone_unref (local);

   return datetime;
 }

 /**
  * g_date_time_new_from_unix_utc:
  * @t: the Unix time
  *
  * Creates a #GDateTime corresponding to the given Unix time @t in UTC.
  *
  * Unix time is the number of seconds that have elapsed since 1970-01-01
  * 00:00:00 UTC.
  *
  * This call can fail (returning %NULL) if @t represents a time outside
  * of the supported range of #GDateTime.
  *
  * You should release the return value by calling g_date_time_unref()
  * when you are done with it.
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  **/
 GDateTime *
 g_date_time_new_from_unix_utc (gint64 t)
 {
   GDateTime *datetime;
   GTimeZone *utc;

-  if (t > G_MAXINT64 / USEC_PER_SECOND)
+  if (t > G_MAXINT64 / USEC_PER_SECOND ||
+      t < G_MININT64 / USEC_PER_SECOND)
     return NULL;

   utc = g_time_zone_new_utc ();
   datetime = g_date_time_new_from_unix (utc, t * USEC_PER_SECOND);
   g_time_zone_unref (utc);

   return datetime;
 }

 /**
  * g_date_time_new_from_timeval_local:
  * @tv: a #GTimeVal
  *
  * Creates a #GDateTime corresponding to the given #GTimeVal @tv in the
  * local time zone.
  *
  * The time contained in a #GTimeVal is always stored in the form of
  * seconds elapsed since 1970-01-01 00:00:00 UTC, regardless of the
  * local time offset.
  *
  * This call can fail (returning %NULL) if @tv represents a time outside
  * of the supported range of #GDateTime.
  *
  * You should release the return value by calling g_date_time_unref()
  * when you are done with it.
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  * Deprecated: 2.62: #GTimeVal is not year-2038-safe. Use
  *    g_date_time_new_from_unix_local() instead.
  **/
 G_GNUC_BEGIN_IGNORE_DEPRECATIONS
 GDateTime *
 g_date_time_new_from_timeval_local (const GTimeVal *tv)
 {
   GDateTime *datetime;
   GTimeZone *local;

   local = g_time_zone_new_local ();
   datetime = g_date_time_new_from_timeval (local, tv);
   g_time_zone_unref (local);

   return datetime;
 }
 G_GNUC_END_IGNORE_DEPRECATIONS

 /**
  * g_date_time_new_from_timeval_utc:
  * @tv: a #GTimeVal
  *
  * Creates a #GDateTime corresponding to the given #GTimeVal @tv in UTC.
  *
  * The time contained in a #GTimeVal is always stored in the form of
  * seconds elapsed since 1970-01-01 00:00:00 UTC.
  *
  * This call can fail (returning %NULL) if @tv represents a time outside
  * of the supported range of #GDateTime.
  *
  * You should release the return value by calling g_date_time_unref()
  * when you are done with it.
  *
  * Returns: a new #GDateTime, or %NULL
  *
  * Since: 2.26
  * Deprecated: 2.62: #GTimeVal is not year-2038-safe. Use
  *    g_date_time_new_from_unix_utc() instead.
  **/
 G_GNUC_BEGIN_IGNORE_DEPRECATIONS
 GDateTime *
 g_date_time_new_from_timeval_utc (const GTimeVal *tv)
 {
   GDateTime *datetime;
   GTimeZone *utc;

   utc = g_time_zone_new_utc ();
   datetime = g_date_time_new_from_timeval (utc, tv);
   g_time_zone_unref (utc);

   return datetime;
 }
 G_GNUC_END_IGNORE_DEPRECATIONS

 /* Parse integers in the form d (week days), dd (hours etc), ddd (ordinal days) or dddd (years) */
 static gboolean
 get_iso8601_int (const gchar *text, gsize length, gint *value)
 {
   gsize i;
   guint v = 0;

   if (length < 1 || length > 4)
     return FALSE;

   for (i = 0; i < length; i++)
     {
       const gchar c = text[i];
       if (c < '0' || c > '9')
         return FALSE;
       v = v * 10 + (c - '0');
     }
